"""Compare phase-two baseline hashes against runs generated by an archived engine."""

import argparse
import csv
import hashlib
import sys
from pathlib import Path
from tempfile import TemporaryDirectory


def check(snapshot: Path, runs: Path) -> tuple[int, int]:
    snapshot = snapshot.resolve()
    package = snapshot / "civsim"
    if not (package / "storage.py").is_file():
        raise ValueError(f"missing archived civsim/storage.py in {snapshot}")
    sys.path.insert(0, str(snapshot))
    from civsim.storage import write_run

    for name, module in sys.modules.copy().items():
        if name == "civsim" or name.startswith("civsim."):
            if not Path(module.__file__).resolve().is_relative_to(package):
                raise ValueError(f"module {name} did not load from the snapshot")

    with runs.open(encoding="utf-8-sig", newline="") as source:
        rows = [row for row in csv.DictReader(source) if row["model_version"] == "1.0"]
    if not rows:
        raise ValueError("no version 1.0 baseline rows in the runs CSV")
    verified = set()
    total_years = 0
    for row in rows:
        seed, years = int(row["seed"]), int(row["years"])
        if (row["labor"], row["order"]) != ("idle", "food-ore-tools"):
            raise ValueError(f"seed {seed}: unexpected rules in a version 1.0 row")
        if (seed, years) in verified:
            raise ValueError(f"seed {seed}: duplicate {years}-year baseline")
        with TemporaryDirectory(prefix="civsim-legacy-") as scratch:
            output = Path(scratch) / "run"
            write_run(output, seed=seed, years=years)
            for filename, field in [("world.json", "initial_sha256"), ("years.jsonl", "years_sha256")]:
                with (output / filename).open("rb") as stream:
                    digest = hashlib.file_digest(stream, "sha256").hexdigest()
                if digest != row[field]:
                    raise ValueError(f"seed {seed}, {filename}: archived {digest}, CSV {row[field]}")
        verified.add((seed, years))
        total_years += years
    return len(verified), total_years


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--snapshot", required=True, type=Path, help="archived project root")
    parser.add_argument("--runs", required=True, type=Path, help="phase-two runs.csv")
    args = parser.parse_args()
    try:
        count, years = check(args.snapshot, args.runs)
    except (ImportError, KeyError, OSError, ValueError) as error:
        parser.exit(1, f"{parser.prog}: {error}\n")
    print(f"world.json SHA-256 matched {count}/{count} baselines.")
    print(f"years.jsonl SHA-256 matched {count}/{count} baselines ({years} annual transitions).")


if __name__ == "__main__":
    main()
